// Time-multiplex a single decoder across two inputs and drive two outputs.
// Common-anode (active-low) segments on seg0[6:0] and seg1[6:0].
module two_digit_mux_from_one_decoder #(
    parameter int CLK_HZ      = 50_000_000, // input clock frequency
    parameter int REFRESH_HZ  = 1000        // per-digit refresh rate (~flicker-free)
) (
    input  logic        clk,
    input  logic        rst_n,        // active-low reset
    input  logic [3:0]  nibble0,      // left (or digit 0) input
    input  logic [3:0]  nibble1,      // right (or digit 1) input
    output logic [6:0]  seg0,         // segments for digit 0, active-low
    output logic [6:0]  seg1          // segments for digit 1, active-low
);

    // Divide clock so we toggle which digit we service at ~REFRESH_HZ.
    // Because we service one digit per toggle, overall full cycle per digit is REFRESH_HZ.
    localparam int TICKS_PER_TOGGLE = CLK_HZ / (REFRESH_HZ * 2);
    localparam int CNTW             = (TICKS_PER_TOGGLE &gt; 1) ? $clog2(TICKS_PER_TOGGLE) : 1;

    logic [CNTW-1:0] div_cnt;
    logic            sel;       // 0 -&gt; service digit0 this slice, 1 -&gt; digit1

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            div_cnt &lt;= '0;
            sel     &lt;= 1'b0;
        end else begin
            if (div_cnt == TICKS_PER_TOGGLE-1) begin
                div_cnt &lt;= '0;
                sel     &lt;= ~sel;
            end else begin
                div_cnt &lt;= div_cnt + 1'b1;
            end
        end
    end

    // Single shared decoder instance
    logic [3:0]  cur_nibble;
    logic [6:0]  seg_decoded;

    always_comb begin
        cur_nibble = (sel == 1'b0) ? nibble0 : nibble1;
    end

    sevenseg_decode_hex_ca u_dec (
        .d  (cur_nibble),
        .seg(seg_decoded)
    );

    // Latch the decoder output into the corresponding digit's segment register
    // on each time slice. Each output holds its last computed value while the
    // other digit is being serviced.
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            seg0 &lt;= 7'h7F; // all off (active-low)
            seg1 &lt;= 7'h7F; // all off
        end else begin
            if (sel == 1'b0) begin
                seg0 &lt;= seg_decoded;
            end else begin
                seg1 &lt;= seg_decoded;
            end
        end
    end

endmodule
