    initial clk_hf = 1'b0;
    always #10 clk_hf = ~clk_hf; // 50 MHz sim clock
    // synthesis translate_on
`endif

    // -------------------------
    // Multiplexing core
    // -------------------------
    dual_sevenseg_mux_core #(
        .REFRESH_BIT(15)   // tune as desired
    ) u_mux (
        .clk   (clk_hf),
        .reset (reset),
        .a     (a),
        .b     (b),
        .seg_a (seg_a),
        .seg_b (seg_b)
    );

